"""PSLE-style items for sci-systems-air-gases (file sci-air-gases.json), all tiers (round sci-fill-air-2026-11-20)."""
from fillkit import add, table, graph, lint
from figs_air import pie, trough, bells, tubes

SUB, FILE = "sci-systems-air-gases", "sci-air-gases.json"
GA, RD = "sci-pat-gases-in-air", "sci-pat-read-data"
B, I, C = "basic", "intermediate", "competent"
P = []
def q(*a): P.append((a[0], a[1], 1) + a[3:])
def W(t, tag, why): return (t, tag, why)
def tb(h, r, w, c): return lambda: table(h, r, w, c)

PIE3 = lambda: pie([(78, "P 78%"), (21, "Q 21%"), (1, "R 1%")], "Gases in air")
BAR3 = lambda: graph(["P", "Q", "R"], [("", [78, 21, 1])], 100, "Gas", "Amount in air (%)", "Gases in air", ystep=20, bars=True)
BAR2 = lambda: graph(["P", "Q"], [("", [78, 21])], 100, "Gas", "Amount in air (%)", "Two gases in air", ystep=20, bars=True)
TXYZ = tb(["Gas", "In air (%)", "Burning candle"], [["X", "78", "goes out"], ["Y", "21", "keeps burning"], ["Z", "0.04", "goes out"]], [60, 100, 130], "Three gases in air")
TIE = tb(["Gas", "Air breathed in (%)", "Air breathed out (%)"], [["Oxygen", "21", "16"], ["Carbon dioxide", "0.04", "4"]], [120, 150, 150], "Breathing test")
TIE3 = tb(["Gas", "Inhaled (%)", "Exhaled (%)"], [["X", "78", "78"], ["Y", "21", "16"], ["Z", "0.04", "4"]], [60, 110, 110], "Gases in breath")

# ---------------- basic ----------------
q("ag-001", B, 1, GA, "What is air?", "A mixture of different gases", [W("Only one gas, oxygen", "one-gas", "Air has oxygen but also nitrogen and other gases."), W("Only one gas, nitrogen", "one-gas", "Nitrogen is the most plentiful gas, but it is not the only one."), W("Empty space with nothing in it", "no-matter", "Air is made of gases, which are matter.")], ["Air is a mixture of gases such as nitrogen, oxygen, carbon dioxide and water vapour."], None)
q("ag-002", B, 1, GA, "Which gas makes up the largest part of air?", "Nitrogen", [W("Oxygen", "most-common", "Oxygen is about one fifth of air, so it is second."), W("Carbon dioxide", "most-common", "Carbon dioxide is only a tiny part of air."), W("Water vapour", "most-common", "Water vapour is a small part of air and its amount changes.")], ["About 78% of air is nitrogen."], None)
q("ag-003", B, 1, GA, "A candle burns in a room. Which gas in the air does the flame use?", "Oxygen", [W("Nitrogen", "wrong-gas", "Nitrogen does not help things burn."), W("Carbon dioxide", "wrong-gas", "Carbon dioxide does not support burning."), W("Water vapour", "wrong-gas", "Water vapour does not help things burn.")], ["Burning needs oxygen."], None)
q("ag-004", B, 1, GA, "Which gas in air do we need to stay alive?", "Oxygen", [W("Carbon dioxide", "wrong-gas", "We give this out when we breathe out."), W("Nitrogen", "wrong-gas", "We breathe nitrogen in and out, but our bodies do not use it."), W("Water vapour", "wrong-gas", "Our bodies do not need water vapour from air for respiration.")], ["Living things use oxygen for respiration."], None)
q("ag-005", B, 1, GA, "Which gas turns limewater milky?", "Carbon dioxide", [W("Oxygen in the air", "wrong-gas", "Oxygen does not change limewater."), W("Nitrogen", "wrong-gas", "Nitrogen does not change limewater."), W("Water vapour", "wrong-gas", "Water vapour does not turn limewater milky.")], ["Carbon dioxide is the gas that makes limewater turn milky."], None)
