q("ag-211", C, 3, GA, "The pie chart shows the gases in exhaled air. Which slice stands for oxygen?", "P", [W("Q", "wrong-slice", "Q is the biggest slice, which is nitrogen."), W("R", "wrong-slice", "R is about 4%, which is carbon dioxide."), W("S", "wrong-slice", "S is the other gases, including water vapour.")], ["Exhaled air has about 16% oxygen."], PIEX)
q("ag-212", C, 3, GA, "In the pie chart of exhaled air, S stands for the other gases including water vapour. Which slice stands for carbon dioxide?", "R", [W("P", "wrong-slice", "P is the oxygen left in exhaled air."), W("Q", "wrong-slice", "Q is nitrogen, the largest part."), W("S", "wrong-slice", "S is the other gases together.")], ["Carbon dioxide in exhaled air is about 4%."], PIEX)
BARO = lambda: graph(["Inhaled", "Exhaled"], [("", [21, 16])], 25, "Air", "Oxygen (%)", "Oxygen in air", ystep=5, bars=True)
q("ag-213", C, 3, RD, "The bar chart shows the oxygen in air breathed in and out. About how much of the air breathed in is used by the body?", "5 percentage points", [W("16 percentage points", "misread", "16 is what is left in exhaled air."), W("21 percentage points", "misread", "21 is the oxygen in inhaled air."), W("37 percentage points", "misread", "Adding the bars is meaningless here.")], ["21 - 16 = 5 percentage points."], BARO)
