q("ag-214", C, 3, RD, "Which statement about water vapour in air does the table support?", "The amount of water vapour in air is not the same in every place", [W("Water vapour is the most plentiful gas in the air in every place", "wrong-idea", "The table shows 1% to 4% only."), W("Desert air has no water vapour", "wrong-idea", "The table shows 1%."), W("The amount of oxygen in air differs in each place", "unsupported", "The table does not show oxygen.")], ["The values 1, 3 and 4 are different."], WV)
q("ag-215", C, 3, GA, "On a cold day, the windows of a full classroom become wet on the inside. Why?", "Water vapour in the pupils' breath turns to water on the glass", [W("The oxygen in the room turns to water on the cold glass", "wrong-gas", "Oxygen does not turn to water."), W("Water comes from outside through the glass slowly", "wrong-idea", "The wet side is the inside."), W("Carbon dioxide turns to water on the cold glass", "wrong-gas", "Carbon dioxide does not turn into water.")], ["Exhaled air has water vapour that condenses on the cold glass."], None)
TGAS = tb(["Gas", "Burning splint", "Limewater"], [["A", "burns brighter", "stays clear"], ["B", "goes out", "turns milky"], ["C", "goes out", "stays clear"]], [60, 120, 120], "Tests on three gases")
q("ag-216", C, 3, RD, "The table shows tests on three gases that are found in air. Which gas is carbon dioxide?", "B", [W("A", "wrong-gas", "A makes the splint burn brighter, which is oxygen."), W("C", "wrong-gas", "C does not change limewater, so it is not carbon dioxide."), W("A and B", "wrong-idea", "Only one gas is carbon dioxide.")], ["Only carbon dioxide turns limewater milky."], TGAS)
q("ag-217", C, 3, RD, "The table shows tests on three gases that are found in air. Which gas is oxygen?", "A", [W("B", "wrong-gas", "B turns limewater milky, which is carbon dioxide."), W("C", "wrong-gas", "C puts out the splint, as nitrogen does."), W("B and C", "wrong-idea", "Both put out the splint, so neither is oxygen.")], ["Oxygen makes things burn more brightly."], TGAS)
q("ag-218", C, 3, GA, "Animals and fires use up oxygen all the time, yet the amount of oxygen in air stays about the same. Which reason helps to explain this?", "Green plants give out oxygen in light", [W("Nitrogen slowly changes into oxygen in the air", "wrong-idea", "Nitrogen does not change into oxygen."), W("Carbon dioxide changes into oxygen in the air", "wrong-idea", "Plants use carbon dioxide, but air does not change it by itself."), W("Water vapour breaks down into oxygen in the air", "wrong-idea", "This does not happen in air.")], ["Plants return oxygen to the air."], None)
q("ag-219", C, 3, GA, "Which statement about air is correct?", "Air is a mixture of gases and its water vapour amount can change", [W("Nitrogen is needed for burning, so it is used up by a flame", "wrong-gas", "Oxygen is the gas needed for burning."), W("Carbon dioxide is the second most plentiful gas in air", "wrong-amount", "Oxygen is second. Carbon dioxide is tiny."), W("Oxygen makes up about half of the air", "wrong-amount", "It is about one fifth.")], ["Air has fixed large parts but variable water vapour."], None)
q("ag-220", C, 3, GA, "A student breathes in and out of a closed plastic bag for two minutes. What happens to the gases in the bag?", "Oxygen goes down and carbon dioxide goes up", [W("Oxygen goes up and carbon dioxide goes down", "reversed", "The student uses oxygen and gives out carbon dioxide."), W("Both oxygen and carbon dioxide go down", "wrong-idea", "The student gives carbon dioxide to the bag."), W("Nitrogen goes down and oxygen goes up", "wrong-gas", "Nitrogen stays about the same.")], ["Respiration uses oxygen and makes carbon dioxide."], None)
q("ag-221", C, 3, GA, "Gas in a jar was tested before and after a candle burned in it. How does the gas after burning compare with the gas before?", "It has less oxygen and more carbon dioxide", [W("It has more oxygen and less carbon dioxide", "reversed", "Burning uses oxygen and makes carbon dioxide."), W("It has less nitrogen and more oxygen", "wrong-gas", "Nitrogen stays about the same."), W("It has the same amount of every gas", "wrong-idea", "Burning changes the gases.")], ["The candle used oxygen and gave out carbon dioxide."], None)
q("ag-222", C, 3, GA, "Limewater is used in the trough instead of water. After the candle goes out, the limewater inside the jar turns milky. What does this show?", "Carbon dioxide was made by the candle", [W("The jar now contains more oxygen than it did before", "wrong-test", "Burning uses oxygen."), W("The candle made nitrogen", "wrong-gas", "Limewater does not test for nitrogen."), W("The limewater has reacted with the glass of the jar", "wrong-idea", "The change is due to carbon dioxide.")], ["Milky limewater means carbon dioxide."], lambda: trough(0, True, caption="Limewater in the trough", liquid="limewater"))
PG = lambda: graph(["0", "2", "4", "6"], [("Light", [21, 22, 23, 24]), ("Dark", [21, 20, 19, 18])], 25, "Time (h)", "Oxygen in box (%)", "A plant in a sealed box", ystep=5, legend="bl")
q("ag-223", C, 3, RD, "A plant was kept in a sealed box in bright light and in the dark. Which conclusion does the graph support?", "In light the plant added oxygen, but in the dark it used oxygen", [W("In light the plant used oxygen, but in the dark it added oxygen", "reversed", "In light the oxygen went up."), W("The plant added oxygen both in light and in the dark", "wrong-idea", "In the dark the oxygen went down."), W("The plant had no effect on oxygen", "wrong-idea", "Both lines change.")], ["Light gives a rise and dark gives a fall."], PG)
q("ag-224", C, 3, GA, "Gas is collected from a jar after a candle has gone out. A burning splint goes out in it and it turns limewater milky. Is it pure carbon dioxide?", "No, it also has nitrogen and some oxygen", [W("Yes, because it turns limewater milky and puts the splint out", "wrong-idea", "Other gases in a mixture do not affect that test."), W("Yes, because the splint goes out", "wrong-idea", "A flame can also go out with low oxygen."), W("No, it is only nitrogen", "wrong-gas", "Nitrogen does not turn limewater milky.")], ["The jar still holds the nitrogen of the original air."], None)
